CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE devices (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), name text NOT NULL, platform text NOT NULL DEFAULT '', last_seen_at timestamptz, UNIQUE(user_id,id));
CREATE TABLE auth_tokens (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text REFERENCES devices(id), kind text NOT NULL CHECK(kind IN ('client','device')), expires_at timestamptz NOT NULL, revoked_at timestamptz, CHECK((kind='device')=(device_id IS NOT NULL)));
CREATE TABLE provider_profiles (device_id text NOT NULL REFERENCES devices(id), id text NOT NULL, user_id text NOT NULL, body jsonb NOT NULL, PRIMARY KEY(device_id,id), FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE TABLE repositories (id text PRIMARY KEY, device_id text NOT NULL REFERENCES devices(id), user_id text NOT NULL, body jsonb NOT NULL, UNIQUE(user_id,id), FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE TABLE tasks (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), repository_id text NOT NULL, body jsonb NOT NULL, UNIQUE(user_id,id), FOREIGN KEY(user_id,repository_id) REFERENCES repositories(user_id,id), CHECK(body->>'status' IN ('inbox','ready','queued','dispatching','running','waiting_input','waiting_quota','completed','failed','unknown')));
CREATE TABLE task_dependencies (user_id text NOT NULL, task_id text NOT NULL, depends_on_id text NOT NULL, PRIMARY KEY(task_id,depends_on_id), FOREIGN KEY(user_id,task_id) REFERENCES tasks(user_id,id) ON DELETE CASCADE, FOREIGN KEY(user_id,depends_on_id) REFERENCES tasks(user_id,id), CHECK(task_id<>depends_on_id));
CREATE TABLE executions (created_at timestamptz NOT NULL DEFAULT now(), observed_at timestamptz, id text PRIMARY KEY, user_id text NOT NULL, task_id text NOT NULL, device_id text NOT NULL, body jsonb NOT NULL, FOREIGN KEY(user_id,task_id) REFERENCES tasks(user_id,id), FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE UNIQUE INDEX one_active_execution_per_task ON executions(task_id) WHERE body->>'state' IN ('dispatching','running','waiting_input','waiting_quota','unknown');
CREATE TABLE sessions (device_id text NOT NULL, profile_id text NOT NULL, id text NOT NULL, user_id text NOT NULL, body jsonb NOT NULL, observed_at timestamptz NOT NULL, PRIMARY KEY(device_id,profile_id,id), FOREIGN KEY(device_id,profile_id) REFERENCES provider_profiles(device_id,id), FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE TABLE commands (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text NOT NULL, execution_id text NOT NULL REFERENCES executions(id), status text NOT NULL CHECK(status IN ('pending','delivered','acknowledged','completed','failed')), payload jsonb NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE INDEX command_delivery ON commands(device_id,status);
CREATE TABLE push_devices (id text NOT NULL, user_id text NOT NULL REFERENCES users(id), platform text NOT NULL CHECK(platform IN ('apns','fcm')), token text NOT NULL, PRIMARY KEY(user_id,id));
CREATE TABLE mutation_journal (user_id text NOT NULL REFERENCES users(id), id text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(user_id,id));
CREATE TABLE agent_events (device_id text NOT NULL REFERENCES devices(id), id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(device_id,id));
CREATE TABLE push_jobs (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), registration_id text NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX queued_tasks ON tasks(user_id,(body->>'status'));
